window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-70438574f0db0359"]={"versions": [{"id": "FIG-70438574f0db0359", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Protokoll- und Bitfeld-Layout (PDU-Format / Paketstruktur) der AUTOSAR Service Discovery (Classic & Adaptive Platform). Das Diagramm spezifiziert das binäre Übertragungsformat der „IPv6 Endpoint Option“ als standardisierte Option innerhalb von SOME/IP-SD-Nachrichten zur Bekanntgabe von Netzwerk-Endpunkten über IPv6.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Die Datenstruktur ist in 32-Bit-Worten (Bit-Offset 0 bis 31) organisiert und umfasst folgende Felder:</p>\n<ul class=\"fig-list\">\n<li><code>Length</code> (Bit 0–15, 16 Bit): Festwert <code>0x0015</code> (21 Byte), definiert die Länge der Option abzüglich der ersten 3 Byte (<code>Length</code> und <code>Type</code>).</li>\n<li><code>Type</code> (Bit 16–23, 8 Bit): Kennung der Option mit dem Festwert <code>0x06</code> für die IPv6 Endpoint Option.</li>\n<li><code>Reserved</code> (Bit 24–31, 8 Bit): Erstes Reservierungsfeld mit Festwert <code>0x00</code>.</li>\n<li><code>IPv6-Address</code> (128 Bit bzw. 4 aufeinanderfolgende 32-Bit-Zeilen): IPv6-Zieladresse des angebotenen oder angeforderten Dienst-Endpunkts.</li>\n<li><code>Reserved</code> (Bit 0–7 der Abschlusszeile, 8 Bit): Zweites Reservierungsfeld mit Festwert <code>0x00</code>.</li>\n<li><code>L4-Proto (TCP/UDP…)</code> (Bit 8–15, 8 Bit): Identifikator des Transportprotokolls der Transportschicht (Layer 4, z. B. TCP oder UDP).</li>\n<li><code>Port Number</code> (Bit 16–31, 16 Bit): Portnummer des Dienst-Endpunkts.</li>\n<li>Maßpfeil <code>Covered by Length (incl. Reserved)</code>: Umspannt alle Bytes ab dem ersten <code>Reserved</code>-Feld (Bit 24 der ersten Zeile) bis zum Ende des Felds <code>Port Number</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Serialisierungsformat. Beim Zusammenstellen einer SOME/IP-SD-Nachricht (z. B. FindService-, OfferService- oder SubscribeEventgroup-Einträge) instanziiert der Service-Discovery-Stack die IPv6 Endpoint Option, setzt die Längenangabe auf 21 Byte (<code>0x0015</code>), den Typ auf <code>0x06</code> und die Reservierungsbytes auf <code>0x00</code>. Anschließend werden die 128-Bit-IPv6-Adresse sowie Layer-4-Protokolltyp und Portnummer in Network-Byte-Order serialisiert. Empfangsseitig dient der Typ <code>0x06</code> dem Demultiplexing der Option und die Längenangabe zur Validierung der PDU-Integrität.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ verbindliches Binärlayout für Entwickler von SOME/IP-Service-Discovery-Stacks:</p>\n<ul class=\"fig-list\">\n<li>Das Längenfeld quantifiziert genau 21 Oktette (<code>0x0015</code>), da es das nachfolgende Reservierungsbyte (<code>Reserved = 0x00</code>), die 16 Byte IPv6-Adresse, das untere Reservierungsbyte, das Layer-4-Protokollbyte und die 2 Byte Portnummer einschließt (1 + 16 + 1 + 1 + 2 = 21 Bytes).</li>\n<li>Die reservierten Felder müssen senderseitig zwingend mit <code>0x00</code> belegt werden.</li>\n<li>Multi-Byte-Ganzzahlen (<code>Length</code>, <code>Port Number</code>) sowie die IPv6-Adresse sind gemäß SOME/IP-Spezifikation im Big-Endian-Format (Network Byte Order) zu übertragen.</li>\n</ul>"}, {"id": "FIG-76d489d86133dbd3", "releases": ["R4.2.2", "R4.3.1", "R18-10_R4.4.0_R1.5.0", "R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Protokoll- und Bitfeld-Layout (PDU-Format / Paketstruktur) der AUTOSAR Service Discovery (Classic & Adaptive Platform). Das Diagramm spezifiziert das binäre Übertragungsformat der „IPv6 Endpoint Option“ als standardisierte Option innerhalb von SOME/IP-SD-Nachrichten zur Bekanntgabe von Netzwerk-Endpunkten über IPv6.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Die Datenstruktur ist in 32-Bit-Worten (Bit-Offset 0 bis 31) organisiert und umfasst folgende Felder:</p>\n<ul class=\"fig-list\">\n<li><code>Length</code> (Bit 0–15, 16 Bit): Festwert <code>0x0015</code> (21 Byte), definiert die Länge der Option abzüglich der ersten 3 Byte (<code>Length</code> und <code>Type</code>).</li>\n<li><code>Type</code> (Bit 16–23, 8 Bit): Kennung der Option mit dem Festwert <code>0x06</code> für die IPv6 Endpoint Option.</li>\n<li><code>Reserved</code> (Bit 24–31, 8 Bit): Erstes Reservierungsfeld mit Festwert <code>0x00</code>.</li>\n<li><code>IPv6-Address</code> (128 Bit bzw. 4 aufeinanderfolgende 32-Bit-Zeilen): IPv6-Zieladresse des angebotenen oder angeforderten Dienst-Endpunkts.</li>\n<li><code>Reserved</code> (Bit 0–7 der Abschlusszeile, 8 Bit): Zweites Reservierungsfeld mit Festwert <code>0x00</code>.</li>\n<li><code>L4-Proto (TCP/UDP…)</code> (Bit 8–15, 8 Bit): Identifikator des Transportprotokolls der Transportschicht (Layer 4, z. B. TCP oder UDP).</li>\n<li><code>Port Number</code> (Bit 16–31, 16 Bit): Portnummer des Dienst-Endpunkts.</li>\n<li>Maßpfeil <code>Covered by Length (incl. Reserved)</code>: Umspannt alle Bytes ab dem ersten <code>Reserved</code>-Feld (Bit 24 der ersten Zeile) bis zum Ende des Felds <code>Port Number</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Serialisierungsformat. Beim Zusammenstellen einer SOME/IP-SD-Nachricht (z. B. FindService-, OfferService- oder SubscribeEventgroup-Einträge) instanziiert der Service-Discovery-Stack die IPv6 Endpoint Option, setzt die Längenangabe auf 21 Byte (<code>0x0015</code>), den Typ auf <code>0x06</code> und die Reservierungsbytes auf <code>0x00</code>. Anschließend werden die 128-Bit-IPv6-Adresse sowie Layer-4-Protokolltyp und Portnummer in Network-Byte-Order serialisiert. Empfangsseitig dient der Typ <code>0x06</code> dem Demultiplexing der Option und die Längenangabe zur Validierung der PDU-Integrität.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ verbindliches Binärlayout für Entwickler von SOME/IP-Service-Discovery-Stacks:</p>\n<ul class=\"fig-list\">\n<li>Das Längenfeld quantifiziert genau 21 Oktette (<code>0x0015</code>), da es das nachfolgende Reservierungsbyte (<code>Reserved = 0x00</code>), die 16 Byte IPv6-Adresse, das untere Reservierungsbyte, das Layer-4-Protokollbyte und die 2 Byte Portnummer einschließt (1 + 16 + 1 + 1 + 2 = 21 Bytes).</li>\n<li>Die reservierten Felder müssen senderseitig zwingend mit <code>0x00</code> belegt werden.</li>\n<li>Multi-Byte-Ganzzahlen (<code>Length</code>, <code>Port Number</code>) sowie die IPv6-Adresse sind gemäß SOME/IP-Spezifikation im Big-Endian-Format (Network Byte Order) zu übertragen.</li>\n</ul>"}, {"id": "FIG-3abc61a8373fdfc2", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Protokoll- und Bitfeld-Layout (PDU-Format / Paketstruktur) der AUTOSAR Service Discovery (Classic & Adaptive Platform). Das Diagramm spezifiziert das binäre Übertragungsformat der „IPv6 Endpoint Option“ als standardisierte Option innerhalb von SOME/IP-SD-Nachrichten zur Bekanntgabe von Netzwerk-Endpunkten über IPv6.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Die Datenstruktur ist in 32-Bit-Worten (Bit-Offset 0 bis 31) organisiert und umfasst folgende Felder:</p>\n<ul class=\"fig-list\">\n<li><code>Length</code> (Bit 0–15, 16 Bit): Festwert <code>0x0015</code> (21 Byte), definiert die Länge der Option abzüglich der ersten 3 Byte (<code>Length</code> und <code>Type</code>).</li>\n<li><code>Type</code> (Bit 16–23, 8 Bit): Kennung der Option mit dem Festwert <code>0x06</code> für die IPv6 Endpoint Option.</li>\n<li><code>Reserved</code> (Bit 24–31, 8 Bit): Erstes Reservierungsfeld mit Festwert <code>0x00</code>.</li>\n<li><code>IPv6-Address</code> (128 Bit bzw. 4 aufeinanderfolgende 32-Bit-Zeilen): IPv6-Zieladresse des angebotenen oder angeforderten Dienst-Endpunkts.</li>\n<li><code>Reserved</code> (Bit 0–7 der Abschlusszeile, 8 Bit): Zweites Reservierungsfeld mit Festwert <code>0x00</code>.</li>\n<li><code>L4-Proto (TCP/UDP…)</code> (Bit 8–15, 8 Bit): Identifikator des Transportprotokolls der Transportschicht (Layer 4, z. B. TCP oder UDP).</li>\n<li><code>Port Number</code> (Bit 16–31, 16 Bit): Portnummer des Dienst-Endpunkts.</li>\n<li>Maßpfeil <code>Covered by Length (incl. Reserved)</code>: Umspannt alle Bytes ab dem ersten <code>Reserved</code>-Feld (Bit 24 der ersten Zeile) bis zum Ende des Felds <code>Port Number</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Serialisierungsformat. Beim Zusammenstellen einer SOME/IP-SD-Nachricht (z. B. FindService-, OfferService- oder SubscribeEventgroup-Einträge) instanziiert der Service-Discovery-Stack die IPv6 Endpoint Option, setzt die Längenangabe auf 21 Byte (<code>0x0015</code>), den Typ auf <code>0x06</code> und die Reservierungsbytes auf <code>0x00</code>. Anschließend werden die 128-Bit-IPv6-Adresse sowie Layer-4-Protokolltyp und Portnummer in Network-Byte-Order serialisiert. Empfangsseitig dient der Typ <code>0x06</code> dem Demultiplexing der Option und die Längenangabe zur Validierung der PDU-Integrität.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ verbindliches Binärlayout für Entwickler von SOME/IP-Service-Discovery-Stacks:</p>\n<ul class=\"fig-list\">\n<li>Das Längenfeld quantifiziert genau 21 Oktette (<code>0x0015</code>), da es das nachfolgende Reservierungsbyte (<code>Reserved = 0x00</code>), die 16 Byte IPv6-Adresse, das untere Reservierungsbyte, das Layer-4-Protokollbyte und die 2 Byte Portnummer einschließt (1 + 16 + 1 + 1 + 2 = 21 Bytes).</li>\n<li>Die reservierten Felder müssen senderseitig zwingend mit <code>0x00</code> belegt werden.</li>\n<li>Multi-Byte-Ganzzahlen (<code>Length</code>, <code>Port Number</code>) sowie die IPv6-Adresse sind gemäß SOME/IP-Spezifikation im Big-Endian-Format (Network Byte Order) zu übertragen.</li>\n</ul>"}], "trans": [{"from": "FIG-70438574f0db0359", "to": "FIG-76d489d86133dbd3", "fr": "R4.1.3", "tr": "R4.2.2", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-76d489d86133dbd3", "to": "FIG-3abc61a8373fdfc2", "fr": "R19-11", "tr": "R20-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
